import struct, wave, sys

def write_wav(path, samples, rate=8000, chans=1, sampwidth=2):
    w = wave.open(path, 'wb')
    w.setnchannels(chans); w.setsampwidth(sampwidth); w.setframerate(rate)
    if sampwidth == 2:
        w.writeframes(b''.join(struct.pack('<h', s) for s in samples))
    elif sampwidth == 1:
        w.writeframes(bytes(s & 0xff for s in samples))
    w.close()

def read_wav(path):
    w = wave.open(path, 'rb')
    n, sw, fr, nf = w.getnchannels(), w.getsampwidth(), w.getframerate(), w.getnframes()
    raw = w.readframes(nf); w.close()
    if sw == 2:
        vals = list(struct.unpack('<%dh' % (len(raw)//2), raw))
    elif sw == 1:
        vals = [b-128 for b in raw]
    elif sw == 4:
        vals = list(struct.unpack('<%di' % (len(raw)//4), raw))
    else:
        vals = list(raw)
    return n, sw, fr, nf, vals

if __name__ == '__main__':
    print(read_wav(sys.argv[1]))
EOF
